1	// {init, transition} adapter over a v2 SAM strict-profile spec module — the
2	// ONLY way into check.mjs's BFS engine. The transition relation is derived
3	// mechanically from the module here; it is never hand-authored and is not an
4	// artifact contract. (It was, once: the 1.x `next(state, action, data)`
5	// module. That surface is gone — see CHANGELOG 8.0.0.)
6	//
7	// Adapted from SysMoBench's tools/js-sam/lean-adapter.cjs (verified unmodified
8	// against v2 in E2-v2), with two deliberate differences:
9	//   - factory form: makeSamAdapter(specModule) wraps an ALREADY-LOADED module
10	//     (the pipeline loads specs through load-spec.mjs, which pins the SAM
11	//     library to the vendored 2.0.0-alpha bundle) instead of the env-var +
12	//     require() selection the SysMoBench explorer needed;
13	//   - rejection detection reads instance({}).lastStep().classification
14	//     ('rejected' — the v2 strict-profile signal) first, keeping the v1
15	//     error-slot 'unexpected action' prefix as a compatibility fallback.
16	//
17	// Semantics:
18	//   init()                -> spec.init(); return sanitized spec.getState()
19	//   step(state, i, data)  -> spec.init() (reset); clear error slot;
20	//                           spec.setState(state); spec.actions[i](data);
21	//                           returns { state, verdict, reason }:
22	//                             verdict 'rejected' — the acceptor rejected; state
23	//                               is the INPUT state (a rejection is a legal,
24	//                               observable no-op, not a fault) and reason is
25	//                               the acceptor's reject(reason), when readable.
26	//                             verdict 'accepted' — state is the post snapshot.
27	//                           Any other model-error content or strict-profile
28	//                           throw propagates, so the checker records it as a
29	//                           violation. step() is the full-fidelity surface:
30	//                           the checker consumes it so rejection semantics
31	//                           (verdict + reason) survive into exploration.
32	//   transition(state, i, data) -> step(state, i, data).state — the bare
33	//                           successor relation, for callers that only need
34	//                           state' (polyrun audit/check-effects, polyvers
35	//                           corpus, mutation wrappers).
36	//
37	// Purity: the checker treats transition() as pure, so the model must be a function
38	// of the INPUT SNAPSHOT alone. The library's setState is MERGE-ONLY (it
39	// assigns keys present in the snapshot and never resets the rest) and
40	// getState OMITS undefined-valued and `internal` modelShape keys — so a bare
41	// setState(state) would leave residue from whatever transition ran last, and
42	// BFS node identity would depend on traversal order. transition() therefore
43	// resets the instance via spec.init() FIRST and merges the snapshot on top:
44	// any key outside the snapshot canonically holds its initial value (the same
45	// semantics sam-tv.mjs gives each replay window). Snapshots are re-serialized
46	// with the __-key/function-stripping replacer so internal keys never leak
47	// into the visited-state set. Async acceptors: generated specs declare
48	// hasAsyncActions: false (acceptor throws land synchronously); a truly async
49	// acceptor's rejection would not be observable mid-BFS — same caveat as the
50	// SysMoBench original.
51	'use strict';
52	
53	// SAM v1 rejected gated intents via the model error slot with this prefix.
54	const REJECTION_PREFIX = 'unexpected action';
55	
56	/** True when the module exports the v2 SAM surface the pipeline targets. */
57	function isSamV2Module(mod) {
58	  return !!mod
59	    && typeof mod.instance === 'function'
60	    && typeof mod.init === 'function'
61	    && typeof mod.getState === 'function'
62	    && typeof mod.setState === 'function'
63	    && mod.actions !== null
64	    && typeof mod.actions === 'object';
65	}
66	
67	/** Strips SAM-internal (__-prefixed) keys and functions from snapshots. */
68	const sanitizeReplacer = (key, value) => {
69	  if (typeof key === 'string' && key.startsWith('__')) return undefined;
70	  if (typeof value === 'function') return undefined;
71	  return value;
72	};
73	
74	/** Build the {init, transition} lean relation over a loaded v2 SAM module. */
75	function makeSamAdapter(spec) {
76	  if (!isSamV2Module(spec)) {
77	    throw new Error('makeSamAdapter: module does not export the v2 SAM surface { instance, init, actions, getState, setState }');
78	  }
79	
80	  const snapshot = () => JSON.parse(JSON.stringify(spec.getState(), sanitizeReplacer));
81	
82	  const accessor = () => spec.instance({});
83	
84	  const clearError = () => {
85	    try {
86	      const state = accessor().state();
87	      if (state && typeof state.clearError === 'function') state.clearError();
88	    } catch { /* pre-v2 instances may lack the accessor; nothing to clear.
89	                 (The sam-lib#28 state-key shadowing this also guarded is fixed
90	                 structurally in 2.0.0-alpha.2 / issue #29.) */ }
91	  };
92	
93	  /** v1-compat error-slot read (strict-profile errors THROW instead). */
94	  const readModelError = () => {
95	    try {
96	      const model = accessor().state();
97	      if (!model || typeof model.hasError !== 'function' || !model.hasError()) return null;
98	      const raw = model.error();
99	      const message = (typeof model.errorMessage === 'function' && model.errorMessage()) || String(raw ?? 'unknown error');
100	      const text = typeof raw === 'string' ? raw : (raw && raw.message) || '';
101	      return { message, isRejection: text.startsWith(REJECTION_PREFIX) };
102	    } catch {
103	      return null;
104	    }
105	  };
106	
107	  const lastStepOf = (action) => {
108	    try {
109	      const acc = accessor();
110	      if (typeof acc.lastStep !== 'function') return null;
111	      const step = acc.lastStep();
112	      if (!step || (step.intent !== undefined && step.intent !== action)) return null;
113	      return step;
114	    } catch {
115	      return null;
116	    }
117	  };
118	
119	  const init = () => {
120	    spec.init();
121	    return snapshot();
122	  };
123	
124	  const step = (state, action, data) => {
125	    // Reset-then-merge: without init(), setState's merge-only semantics let
126	    // hidden state leak between transitions and node identity becomes
127	    // traversal-order-dependent (states wrongly merged or missed).
128	    spec.init();
129	    clearError();
130	    spec.setState(state);
131	    // Entry snapshot: the observable state the model actually holds at the
132	    // start of this transition (init values merged with `state`). Used below
133	    // to detect an OBSERVABLE mutate-then-reject.
134	    const entry = snapshot();
135	    const handler = spec.actions[action];
136	    if (typeof handler !== 'function') {
137	      throw new Error(`action '${action}' is not exported by the spec`);
138	    }
