140	    const last = lastStepOf(action);
141	    if (last && last.classification === 'rejected') {
142	      // lastStep() classifies 'rejected' whenever reject() was called — even
143	      // if the acceptor mutated the model FIRST. Treating that as a pure
144	      // no-op would explore an identity transition the replayer (which reads
145	      // getState() and sees the mutation) would fail: the two halves of the
146	      // pipeline would contradict each other on the same spec. A rejection
147	      // that OBSERVABLY mutated is therefore a spec defect. The snapshot
148	      // comparison ALONE is the authoritative test: under sam-pattern 2.1
149	      // primes the remaining mutate-then-reject path is a deep/nested write
150	      // through the shallow-frozen pre-state, which the library reports with
151	      // step.mutations EMPTY — gating on the mutations list would wave the
152	      // defect through. (`internal`-key writes stay invisible to snapshot()
153	      // and to the replayer alike, so they still pass here, as they should.)
154	      if (JSON.stringify(snapshot()) !== JSON.stringify(entry)) {
155	        const what = Array.isArray(last.mutations) && last.mutations.length > 0
