192	function domainFromManifest(spec) {
193	  const manifest = spec.instance({}).manifest();
194	  const intents = (manifest && manifest.intents) || {};
195	  const intentNames = Object.keys(intents);
196	  const steps = [];
197	  const notes = [];
198	  for (const [action, decl] of Object.entries(intents)) {
