208	        if (entry.length === 0) steps.push({ action, data: {} });
209	        else if (entry.length === 1) steps.push({ action, data: entry[0] });
210	        else notes.push(`multi-argument domain entry for ${action} (${entry.length} args) is not representable as a single window payload — skipped`);
