1	// Explicit-state model checker for a SAM v2 strict-profile module.
2	//
3	// This is the SECOND half of the method. Replay (sam-tv.mjs) checks whether a
4	// derived spec CONFORMS to real traces — it finds a bug only when the spec
5	// DISAGREES with the code, which a faithful spec does not (see
6	// eval/FINDING-faithful-reproduction.md). This checker does what you actually
7	// write a spec FOR: it ITERATES the module's transition relation exhaustively
8	// — every reachable state from init() over the finite (intent, data) domain
9	// the module's own manifest() declares — and checks INVARIANTS (rules encoding
10	// intent) at each state and transition. A faithful spec that copied a bug
11	// will, when explored, REACH a state that violates an intent-invariant, with a
12	// shortest counterexample path. That is a bug the replay cannot see.
13	//
14	// The transition relation is NEVER hand-authored. It is derived mechanically
15	// from the SAM module by scripts/sam-adapter.cjs (makeSamAdapter), which is
16	// the only supported way into the explorer below.
17	//
18	// Deterministic: no API, no randomness, no clock.
19	//
20	// Module usage:  check({ specModule, contract, invariants, maxStates, initialStates })
21	// CLI:  node check.mjs --spec <mod.js> --contract <c.json> --invariants <inv.mjs> [--initial-states <states.json>] [--max-states N] [--json out]
22	import { readFileSync } from 'node:fs';
23	import { resolve } from 'node:path';
24	import { pathToFileURL, fileURLToPath } from 'node:url';
25	import { loadSpec, stable, dataFieldsOf } from './load-spec.mjs';
26	import samAdapter from './sam-adapter.cjs';
27	
28	const { isSamV2Module, makeSamAdapter, domainFromManifest } = samAdapter;
29	
30	// Re-export the shared loader (eval scripts and older callers import it from
31	// here). ONE loader for the whole pipeline lives in load-spec.mjs.
32	export { loadSpec };
33	
34	// ── Build the (action, data) domain from the contract + observed traces ────
35	// dataDomain in the contract wins; otherwise values are inferred from the trace
36	// corpus; an action with no data fields contributes a single {} step.
37	//
38	// NOT the checker's exploration domain — that comes from the module's own
39	// manifest() (sam-adapter.domainFromManifest). This is the CONTRACT-side view,
40	// used to report declared-but-unenumerable actions (polygen's domain-gap
41	// notes, polynv's grade).
42	export function buildDomain(contract, windows = []) {
43	  const actions = Object.keys(contract.actions || {});
44	  const observed = {}; // action -> field -> Set(values)
45	  for (const w of windows) {
46	    const d = w.data || {};
47	    observed[w.action] = observed[w.action] || {};
48	    for (const [k, val] of Object.entries(d)) {
49	      // stable(): key-order-insensitive dedup (trace data is JSON-clean, so
50	      // stable output parses back with JSON.parse below).
51	      (observed[w.action][k] = observed[w.action][k] || new Set()).add(stable(val));
52	    }
53	  }
54	  const steps = []; // { action, data }
55	  const notes = [];
56	  for (const action of actions) {
57	    // dataFieldsOf: the SAME accessor build_prompt uses, so a contract written
58	    // with `data:` instead of `dataFields:` gets the same fields in the
59	    // explored domain as in the generation prompt.
60	    const fields = Object.keys(dataFieldsOf(contract.actions[action]));
61	    if (fields.length === 0) { steps.push({ action, data: {} }); continue; }
62	    const perField = fields.map((f) => {
63	      const fromContract = contract.dataDomain?.[action]?.[f];
64	      if (Array.isArray(fromContract)) return fromContract;
65	      const inferred = observed[action]?.[f];
66	      if (inferred && inferred.size) return [...inferred].map((s) => JSON.parse(s));
67	      notes.push(`no domain for ${action}.${f} (no contract dataDomain, none in traces) — skipped`);
68	      return [];
69	    });
70	    if (perField.some((vals) => vals.length === 0)) continue; // can't enumerate this action
71	    // cartesian product over the fields
72	    let combos = [{}];
73	    fields.forEach((f, i) => {
74	      const next = [];
75	      for (const c of combos) for (const v of perField[i]) next.push({ ...c, [f]: v });
76	      combos = next;
77	    });
78	    for (const data of combos) steps.push({ action, data });
79	  }
80	  return { steps, notes };
81	}
82	
83	/**
84	 * Explore the reachable state graph of a spec and check invariants. The spec
85	 * is a v2 SAM strict-profile module ({instance, init, actions, getState,
86	 * setState}), driven through scripts/sam-adapter.cjs with manifest() domains
87	 * — or, for internal callers only, an already-adapted {init, transition}
88	 * relation together with an explicit `steps` domain.
89	 * invariants = { stateInvariants: [{name, pred:(state)=>bool}],
90	 *                transitionInvariants: [{name, pred:(pre,action,data,post)=>bool}] }
91	 * A predicate returns TRUE when the rule HOLDS; a FALSE (or throw) is a violation.
92	 * Every check runs a determinism double-pass: two identical explorations whose
93	 * digests differ add a 'deterministic-exploration' violation (kind
94	 * 'nondeterminism') and set result.nondeterministic.
95	 */
96	// initialStates: additional states seeded into the BFS frontier alongside
97	// init() — the versioning use (docs/VERSIONING.md, polyvers): explore the
98	// machine's rules FROM live fleet snapshots, so "can any currently existing
99	// instance be driven to a violation" becomes the same exhaustive check as
100	// "is the machine correct from init". Seeds dedupe against init and each
101	// other by stable(); counterexample paths record whether they start at init
102	// or at a seed.
103	// steps: an explicit (action, data) domain override — [{action, data}] — used
104	// by callers that must explore two modules over the SAME alphabet (polynv's
105	// mutation grade drives adapter-wrapped mutants with the original module's
