'use strict';

// SAM v2 strict-profile specification of src/host.impl.ts, bounded to two carts
// ('a', 'b'). The network is the sorted list of in-flight messages, each written
// "<Action>:<cart>" (the cart is the sender for Reserve/Charge/Release and the
// receiver for the replies). Reserve qty, Charge amount and Release qty are the
// cart's items, which no longer change once the cart has checked out.
// DELIVER delivers one in-flight message, in any order.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CARTS = ['a', 'b'];
const MAX_ITEMS = 2;
const CHARGE_LIMIT = 4;
const MESSAGE_KINDS = ['Reserve', 'Reserved', 'OutOfStock', 'Charge', 'Charged', 'Declined', 'Release'];

// status 'none' = never opened
const INITIAL_STATE = {
  carts: { a: { status: 'none', items: 0 }, b: { status: 'none', items: 0 } },
  available: 2,
  reserved: 0,
  charged: 0,
  declining: false,
  net: [],
};

const cartDomain = CARTS.map((cart) => ({ cart }));
const msgDomain = [];
for (const kind of MESSAGE_KINDS) for (const cart of CARTS) msgDomain.push({ msg: `${kind}:${cart}` });

const withCart = (model, cart, patch) => ({ ...model.carts, [cart]: { ...model.carts[cart], ...patch } });
const addMsgs = (net, ...msgs) => [...net, ...msgs].sort();
const removeMsg = (net, msg) => {
  const i = net.indexOf(msg);
  return [...net.slice(0, i), ...net.slice(i + 1)];
};

const cartIntent = { action: (data = {}) => ({ ...data }), schema: { cart: { type: 'string', required: true } }, domain: cartDomain };
const noData = { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] };

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      carts: { type: 'object' },
      available: { type: 'number' },
      reserved: { type: 'number' },
      charged: { type: 'number' },
      declining: { type: 'boolean' },
      net: { type: 'array' },
    },
    actions: {
      OPEN: cartIntent,
      ADD: cartIntent,
      CHECKOUT: cartIntent,
      CANCEL: cartIntent,
      DECLINE_CARDS: noData,
      ACCEPT_CARDS: noData,
      DELIVER: { action: (data = {}) => ({ ...data }), schema: { msg: { type: 'string', required: true } }, domain: msgDomain },
    },
    acceptors: {
      OPEN: (model) => ({ cart }, { reject, next, unchanged }) => {
        if (model.carts[cart].status !== 'none') return reject('cart-exists');
        next.carts = withCart(model, cart, { status: 'open', items: 0 });
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      ADD: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (c.status !== 'open') return reject('not-open');
        if (c.items >= MAX_ITEMS) return reject('cart-full');
        next.carts = withCart(model, cart, { items: c.items + 1 });
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      CHECKOUT: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (c.status !== 'open') return reject('not-open');
        if (c.items < 1) return reject('cart-empty');
        next.carts = withCart(model, cart, { status: 'reserving' });
        next.net = addMsgs(model.net, `Reserve:${cart}`);
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      CANCEL: (model) => ({ cart }, { reject, next, unchanged }) => {
        const s = model.carts[cart].status;
        if (s === 'open') next.carts = withCart(model, cart, { status: 'cancelled' });
        else if (s === 'reserving') next.carts = withCart(model, cart, { status: 'cancelling' });
        else return reject(s === 'paying' ? 'payment-in-progress' : 'not-cancellable');
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      DECLINE_CARDS: (model) => (_p, { reject, next, unchanged }) => {
        if (model.declining) return reject('already-declining');
        next.declining = true;
        unchanged('carts', 'available', 'reserved', 'charged', 'net');
      },
      ACCEPT_CARDS: (model) => (_p, { reject, next, unchanged }) => {
        if (!model.declining) return reject('already-accepting');
        next.declining = false;
