const msgDomain = [];
for (const kind of MESSAGE_KINDS) for (const cart of CARTS) msgDomain.push({ msg: `${kind}:${cart}` });

const withCart = (model, cart, patch) => ({ ...model.carts, [cart]: { ...model.carts[cart], ...patch } });
const addMsgs = (net, ...msgs) => [...net, ...msgs].sort();
const removeMsg = (net, msg) => {
  const i = net.indexOf(msg);
  return [...net.slice(0, i), ...net.slice(i + 1)];
};

const cartIntent = { action: (data = {}) => ({ ...data }), schema: { cart: { type: 'string', required: true } }, domain: cartDomain };
const noData = { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] };

