  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      carts: { type: 'object' },
      available: { type: 'number' },
      reserved: { type: 'number' },
      charged: { type: 'number' },
      declining: { type: 'boolean' },
      net: { type: 'array' },
    },
    actions: {
      OPEN: cartIntent,
      ADD: cartIntent,
      CHECKOUT: cartIntent,
      CANCEL: cartIntent,
      DECLINE_CARDS: noData,
      ACCEPT_CARDS: noData,
      DELIVER: { action: (data = {}) => ({ ...data }), schema: { msg: { type: 'string', required: true } }, domain: msgDomain },
