            if (c.status === 'reserving') next.carts = withCart(model, cart, { status: 'failed' });
            else if (c.status === 'cancelling') next.carts = withCart(model, cart, { status: 'cancelled' });
            else unchanged('carts');
            next.net = net;
            unchanged('available', 'reserved', 'charged', 'declining');
            return;
          }
          case 'Charged': {
            if (c.status === 'paying') next.carts = withCart(model, cart, { status: 'paid' });
            else unchanged('carts');
            next.net = net;
            unchanged('available', 'reserved', 'charged', 'declining');
            return;
          }
          case 'Declined': {
            if (c.status === 'paying') {
              next.carts = withCart(model, cart, { status: 'failed' });
              next.net = addMsgs(net, `Release:${cart}`);
            } else {
              next.net = net;
              unchanged('carts');
            }
            unchanged('available', 'reserved', 'charged', 'declining');
            return;
          }
          default:
            return reject('unknown-message');
        }
      },
    },
    reactors: [],
  },
