            }
            unchanged('carts', 'available', 'reserved', 'declining');
            return;
          }
          case 'Reserved': {
            if (c.status === 'reserving') {
              next.carts = withCart(model, cart, { status: 'paying' });
              next.net = addMsgs(net, `Charge:${cart}`);
            } else if (c.status === 'cancelling') {
              next.carts = withCart(model, cart, { status: 'cancelled' });
              next.net = addMsgs(net, `Release:${cart}`);
            } else {
              next.net = net;
              unchanged('carts');
            }
            unchanged('available', 'reserved', 'charged', 'declining');
            return;
          }
          case 'OutOfStock': {
            if (c.status === 'reserving') next.carts = withCart(model, cart, { status: 'failed' });
            else if (c.status === 'cancelling') next.carts = withCart(model, cart, { status: 'cancelled' });
