    pred: (s) => s.reserved === unitsWhere(s, (c, k) => ['paid', 'paying', 'declined'].includes(c.status)
      || (['reserving', 'cancelling'].includes(c.status) && inFlight(s, 'Reserved', k))
      || inFlight(s, 'Release', k)),
  },
  // The total charged covers paid carts, paying carts whose Charged answer is in flight,
  // and returned carts whose Refund is still in flight.
  {
    name: 'charged-accounting',
    pred: (s) => s.charged === unitsWhere(s, (c, k) => c.status === 'paid'
      || (c.status === 'paying' && inFlight(s, 'Charged', k))
      || (c.status === 'returned' && inFlight(s, 'Refund', k))),
  },
];

export const transitionInvariants = [
  {
    name: 'paid-only-after-charge-delivered',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      post.carts[k].status !== 'paid' || pre.carts[k].status === 'paid'
      || (action === 'DELIVER' && data.msg === `Charged:${k}` && pre.carts[k].status === 'paying')),
  },
  {
    name: 'paying-only-after-reserved',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      post.carts[k].status !== 'paying' || pre.carts[k].status === 'paying'
      || (action === 'DELIVER' && data.msg === `Reserved:${k}` && pre.carts[k].status === 'reserving')),
  },
  {
    name: 'returned-only-from-paid-with-refund-and-release',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      post.carts[k].status !== 'returned' || pre.carts[k].status === 'returned'
      || (action === 'RETURN' && data.cart === k && pre.carts[k].status === 'paid'
        && inFlight(post, 'Refund', k) && inFlight(post, 'Release', k))),
  },
  {
    name: 'items-frozen-after-checkout',
    pred: (pre, _a, _d, post) => Object.keys(post.carts).every((k) =>
      ['none', 'open'].includes(pre.carts[k].status) || pre.carts[k].items === post.carts[k].items),
  },
  {
    name: 'terminal-statuses-final',
    pred: (pre, _a, _d, post) => Object.keys(post.carts).every((k) =>
      !TERMINAL.includes(pre.carts[k].status) || pre.carts[k].status === post.carts[k].status),
  },
  {
    name: 'paid-leaves-only-by-return',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      pre.carts[k].status !== 'paid' || post.carts[k].status === 'paid'
      || (action === 'RETURN' && data.cart === k && post.carts[k].status === 'returned')),
  },
  {
    name: 'replies-only-to-pending-requests',
    pred: (pre, action, data, post) => action !== 'DELIVER' || !data.msg.startsWith('Reserve:') || !pre.net.includes(data.msg)
      || post.net.some((m) => (m === `Reserved:${cartOf(data.msg)}` || m === `OutOfStock:${cartOf(data.msg)}`)),
  },
];

