import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

test('happy path: paid cart keeps its units reserved and is charged', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  await h.add('a');
  await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.checkout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'reserving', items: 2 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('unknown cart refused; empty checkout refused; cart null', async () => {
  const h = await createHost();
  assert.equal((await h.add('x')).ok, false);
  assert.equal((await h.checkout('x')).ok, false);
  assert.equal((await h.cancel('x')).ok, false);
  assert.equal(await h.cart('x'), null);
  await h.open('x');
  assert.equal((await h.checkout('x')).ok, false);
});

test('decline releases units', async () => {
  const h = await createHost();
  assert.equal((await h.acceptCards()).ok, false);
  assert.deepEqual(await h.declineCards(), { ok: true });
  assert.equal((await h.declineCards()).ok, false);
  await h.open('a'); await h.add('a'); await h.checkout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
});

test('out of stock fails; cancel while reserving', async () => {
  const h = await createHost();
  for (const c of ['a', 'b']) { await h.open(c); await h.add(c); await h.add(c); await h.checkout(c); }
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.cart('a'))!.status, 'cancelling');
  assert.equal((await h.cancel('a')).ok, false);
  const [ra] = (await h.inFlight()).filter((m) => m.from === 'a');
  await h.deliver(ra.id); // a reserves first
  const [rb] = (await h.inFlight()).filter((m) => m.from === 'b');
  await h.deliver(rb.id); // b out of stock
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'cancelled');
  assert.equal((await h.cart('b'))!.status, 'failed');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

test('cancel refused while paying', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.checkout('a');
  await h.deliver((await h.inFlight())[0].id);
  await h.deliver((await h.inFlight())[0].id);
  assert.equal((await h.cart('a'))!.status, 'paying');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'paid');
  assert.equal((await h.cancel('a')).ok, false);
});

test('return refunds and releases; returned cart accepts no command', async () => {
  const h = await createHost();
  assert.equal((await h.returnCart('a')).ok, false);
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.returnCart('a')).ok, false);
  await h.checkout('a'); await h.deliverAll();
  assert.deepEqual(await h.returnCart('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'returned', items: 2 });
  const msgs = (await h.inFlight()).map(({ from, to, action, data }) => ({ from, to, action, data }));
  assert.deepEqual(msgs.sort((x, y) => x.action.localeCompare(y.action)), [
    { from: 'a', to: 'payments', action: 'Refund', data: { amount: 2 } },
    { from: 'a', to: 'inventory', action: 'Release', data: { qty: 2 } },
  ]);
  for (const cmd of ['add', 'checkout', 'cancel', 'returnCart'] as const) assert.equal((await h[cmd]('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await inFlightCount(h), 0);
});

async function inFlightCount(h: Host) { return (await h.inFlight()).length; }

test('charge limit declines while an earlier refund is in flight', async () => {
  const h = await createHost();
  const deliverRelease = async (c: string) => {
    const m = (await h.inFlight()).find((x) => x.action === 'Release' && x.from === c)!;
    await h.deliver(m.id);
  };
  for (const c of ['a', 'b']) {
    await h.open(c); await h.add(c); await h.add(c); await h.checkout(c);
    // deliver everything except refunds
    for (let ms = await h.inFlight(); ms.some((m) => m.action !== 'Refund'); ms = await h.inFlight()) {
      await h.deliver(ms.find((m) => m.action !== 'Refund')!.id);
    }
    assert.equal((await h.cart(c))!.status, 'paid');
    await h.returnCart(c);
    await deliverRelease(c);
  }
  assert.deepEqual(await h.payments(), { charged: 4, declining: false });
  await h.open('c'); await h.add('c'); await h.checkout('c');
  for (let ms = await h.inFlight(); ms.some((m) => m.action !== 'Refund'); ms = await h.inFlight()) {
    await h.deliver(ms.find((m) => m.action !== 'Refund')!.id);
  }
  assert.equal((await h.cart('c'))!.status, 'failed');
  await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

// Seeded random scenarios with random delivery order; checks the brief's conclusion.
function rng(seed: number) {
  return () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
}

async function conclusion(h: Host, ids: string[]) {
  let paidUnits = 0;
  for (const id of ids) {
    const c = await h.cart(id);
    if (c && c.status === 'paid') paidUnits += c.items;
    if (c) assert.ok(!['reserving', 'paying', 'cancelling'].includes(c.status) || false, `cart ${id} stuck ${c.status}`);
  }
  const s = await h.stock();
  const p = await h.payments();
  assert.equal(s.available + s.reserved, 2);
  assert.equal(s.reserved, paidUnits);
  assert.equal(p.charged, paidUnits);
}

test('random interleavings satisfy the conclusion', async () => {
  for (let seed = 1; seed <= 400; seed++) {
    const r = rng(seed);
    const h = await createHost();
    const ids = ['a', 'b', 'c'];
    for (let step = 0; step < 40; step++) {
      const id = ids[Math.floor(r() * ids.length)];
      const k = r();
      if (k < 0.05) await h.returnCart(id);
      else if (k < 0.15) await h.open(id);
      else if (k < 0.35) await h.add(id);
      else if (k < 0.5) await h.checkout(id);
      else if (k < 0.6) await h.cancel(id);
      else if (k < 0.65) await h.declineCards();
      else if (k < 0.7) await h.acceptCards();
      else {
        const msgs = await h.inFlight();
        if (msgs.length) await h.deliver(msgs[Math.floor(r() * msgs.length)].id);
      }
    }
    await h.deliverAll();
    await conclusion(h, ids);
  }
});

