    actions: {
      OPEN: cartIntent(),
      ADD: cartIntent(),
      CHECKOUT: cartIntent(),
      CANCEL: cartIntent(),
      RETURN: cartIntent(),
      RETRY: cartIntent(),
      ABANDON: cartIntent(),
      PAYMENT_TIMEOUT: cartIntent(),
      DECLINE_CARDS: noData(),
      ACCEPT_CARDS: noData(),
      DELIVER: { action: (data = {}) => ({ ...data }), schema: { msg: { type: 'string', required: true } }, domain: msgDomain },
    },
    acceptors: {
      OPEN: (model) => ({ cart }, { reject, next, unchanged }) => {
        if (model.carts[cart].status !== 'none') return reject('cart-exists');
        next.carts = withCart(model, cart, { status: 'open', items: 0 });
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      ADD: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (c.status !== 'open') return reject('not-open');
        if (c.items >= MAX_ITEMS) return reject('cart-full');
        next.carts = withCart(model, cart, { items: c.items + 1 });
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      CHECKOUT: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (c.status !== 'open') return reject('not-open');
        if (c.items < 1) return reject('cart-empty');
        next.carts = withCart(model, cart, { status: 'reserving' });
        next.net = addMsgs(model.net, `Reserve:${cart}`);
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      CANCEL: (model) => ({ cart }, { reject, next, unchanged }) => {
        const s = model.carts[cart].status;
        if (s === 'open') next.carts = withCart(model, cart, { status: 'cancelled' });
        else if (s === 'reserving') next.carts = withCart(model, cart, { status: 'cancelling' });
        else return reject(s === 'paying' ? 'payment-in-progress' : 'not-cancellable');
        unchanged('available', 'reserved', 'charged', 'declining', 'net');
      },
      RETURN: (model) => ({ cart }, { reject, next, unchanged }) => {
        if (model.carts[cart].status !== 'paid') return reject('not-paid');
        next.carts = withCart(model, cart, { status: 'returned' });
        next.net = addMsgs(model.net, `Refund:${cart}`, `Release:${cart}`);
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      RETRY: (model) => ({ cart }, { reject, next, unchanged }) => {
        if (model.carts[cart].status !== 'declined') return reject('not-declined');
        next.carts = withCart(model, cart, { status: 'paying' });
        next.net = addMsgs(model.net, `Charge:${cart}`);
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      ABANDON: (model) => ({ cart }, { reject, next, unchanged }) => {
        if (model.carts[cart].status !== 'declined') return reject('not-declined');
        next.carts = withCart(model, cart, { status: 'failed' });
        next.net = addMsgs(model.net, `Release:${cart}`);
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      PAYMENT_TIMEOUT: (model) => ({ cart }, { reject, next, unchanged }) => {
        if (model.carts[cart].status !== 'paying') return reject('not-paying');
        next.carts = withCart(model, cart, { status: 'abandoning' });
        next.net = addMsgs(model.net, `Release:${cart}`);
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      DECLINE_CARDS: (model) => (_p, { reject, next, unchanged }) => {
        if (model.declining) return reject('already-declining');
        next.declining = true;
        unchanged('carts', 'available', 'reserved', 'charged', 'net');
      },
      ACCEPT_CARDS: (model) => (_p, { reject, next, unchanged }) => {
        if (!model.declining) return reject('already-accepting');
        next.declining = false;
        unchanged('carts', 'available', 'reserved', 'charged', 'net');
      },
      DELIVER: (model) => ({ msg }, { reject, next, unchanged }) => {
        if (!model.net.includes(msg)) return reject('not-in-flight');
        const [kind, cart] = msg.split(':');
        const c = model.carts[cart];
        const net = removeMsg(model.net, msg);
        switch (kind) {
          case 'Reserve': {
            if (model.available >= c.items) {
              next.available = model.available - c.items;
              next.reserved = model.reserved + c.items;
              next.net = addMsgs(net, `Reserved:${cart}`);
            } else {
              next.net = addMsgs(net, `OutOfStock:${cart}`);
              unchanged('available', 'reserved');
            }
            unchanged('carts', 'charged', 'declining');
            return;
          }
          case 'Release': {
            const qty = Math.min(c.items, model.reserved);
            next.available = model.available + qty;
            next.reserved = model.reserved - qty;
            next.net = net;
            unchanged('carts', 'charged', 'declining');
            return;
          }
          case 'Refund': {
            next.charged = model.charged - Math.min(c.items, model.charged);
            next.net = net;
            unchanged('carts', 'available', 'reserved', 'declining');
            return;
          }
          case 'Charge': {
            if (!model.declining && model.charged + c.items <= CHARGE_LIMIT) {
              next.charged = model.charged + c.items;
              next.net = addMsgs(net, `Charged:${cart}`);
            } else {
              next.net = addMsgs(net, `Declined:${cart}`);
              unchanged('charged');
            }
            unchanged('carts', 'available', 'reserved', 'declining');
            return;
          }
          case 'Reserved': {
            if (c.status === 'reserving') {
              next.carts = withCart(model, cart, { status: 'paying' });
              next.net = addMsgs(net, `Charge:${cart}`);
            } else if (c.status === 'cancelling') {
              next.carts = withCart(model, cart, { status: 'cancelled' });
              next.net = addMsgs(net, `Release:${cart}`);
            } else {
              next.net = net;
              unchanged('carts');
            }
            unchanged('available', 'reserved', 'charged', 'declining');
            return;
          }
          case 'OutOfStock': {
            if (c.status === 'reserving') next.carts = withCart(model, cart, { status: 'failed' });
            else if (c.status === 'cancelling') next.carts = withCart(model, cart, { status: 'cancelled' });
            else unchanged('carts');
            next.net = net;
            unchanged('available', 'reserved', 'charged', 'declining');
            return;
          }
          case 'Charged': {
            if (c.status === 'paying') {
              next.carts = withCart(model, cart, { status: 'paid' });
              next.net = net;
            } else if (c.status === 'abandoning') {
              next.carts = withCart(model, cart, { status: 'failed' });
              next.net = addMsgs(net, `Refund:${cart}`);
            } else {
              next.net = net;
              unchanged('carts');
            }
            unchanged('available', 'reserved', 'charged', 'declining');
            return;
          }
          case 'Declined': {
            if (c.status === 'paying') next.carts = withCart(model, cart, { status: 'declined' });
            else if (c.status === 'abandoning') next.carts = withCart(model, cart, { status: 'failed' });
            else unchanged('carts');
            next.net = net;
            unchanged('available', 'reserved', 'charged', 'declining');
            return;
          }
          default:
            return reject('unknown-message');
        }
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  OPEN: (data = {}) => intents.OPEN(data),
  ADD: (data = {}) => intents.ADD(data),
  CHECKOUT: (data = {}) => intents.CHECKOUT(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  RETURN: (data = {}) => intents.RETURN(data),
  RETRY: (data = {}) => intents.RETRY(data),
  ABANDON: (data = {}) => intents.ABANDON(data),
  DECLINE_CARDS: (data = {}) => intents.DECLINE_CARDS(data),
  ACCEPT_CARDS: (data = {}) => intents.ACCEPT_CARDS(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

