tool_use_result.originalFile:
// Rules the brief requires, over the state of spec/checkout.cjs.
const entries = (s) => Object.entries(s.carts);
const carts = (s) => Object.values(s.carts);
const unitsWhere = (s, pred) => entries(s).filter(([k, c]) => pred(c, k)).reduce((n, [, c]) => n + c.items, 0);
const paidUnits = (s) => unitsWhere(s, (c) => c.status === 'paid');
const quiescent = (s) => s.net.length === 0;
const inFlight = (s, kind, k) => s.net.includes(`${kind}:${k}`);
const cartOf = (msg) => msg.split(':')[1];
const TERMINAL = ['failed', 'cancelled', 'returned'];

export const stateInvariants = [
  { name: 'stock-conserved', pred: (s) => s.available + s.reserved === 2 && s.available >= 0 && s.reserved >= 0 },
  { name: 'charge-limit', pred: (s) => s.charged >= 0 && s.charged <= 4 },
  // Change 2: a declined cart keeps its units reserved while the customer decides.
  { name: 'quiescent-reserved-is-paid-or-declined-units', pred: (s) => !quiescent(s) || s.reserved === unitsWhere(s, (c) => c.status === 'paid' || c.status === 'declined') },
  { name: 'quiescent-charged-is-paid-units', pred: (s) => !quiescent(s) || s.charged === paidUnits(s) },
  { name: 'quiescent-no-cart-in-progress', pred: (s) => !quiescent(s) || carts(s).every((c) => !['reserving', 'paying', 'cancelling'].includes(c.status)) },
  // Exact accounting at every step: units are reserved for paid, paying and declined carts,
  // for carts whose Reserved answer is in flight, and for carts whose Release is in flight.
  {
    name: 'reserved-accounting',
    pred: (s) => s.reserved === unitsWhere(s, (c, k) => ['paid', 'paying', 'declined'].includes(c.status)
      || (['reserving', 'cancelling'].includes(c.status) && inFlight(s, 'Reserved', k))
      || inFlight(s, 'Release', k)),
  },
  // The total charged covers paid carts, paying carts whose Charged answer is in flight,
  // and returned carts whose Refund is still in flight.
  {
    name: 'charged-accounting',
    pred: (s) => s.charged === unitsWhere(s, (c, k) => c.status === 'paid'
      || (c.status === 'paying' && inFlight(s, 'Charged', k))
      || (c.status === 'returned' && inFlight(s, 'Refund', k))),
  },
];

export const transitionInvariants = [
  {
    name: 'paid-only-after-charge-delivered',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      post.carts[k].status !== 'paid' || pre.carts[k].status === 'paid'
      || (action === 'DELIVER' && data.msg === `Charged:${k}` && pre.carts[k].status === 'paying')),
  },
  {
    name: 'paying-only-after-reserved',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      post.carts[k].status !== 'paying' || pre.carts[k].status === 'paying'
      || (action === 'DELIVER' && data.msg === `Reserved:${k}` && pre.carts[k].status === 'reserving')
      || (action === 'RETRY' && data.cart === k && pre.carts[k].status === 'declined' && inFlight(post, 'Charge', k))),
  },
  {
    name: 'declined-only-after-charge-declined',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      post.carts[k].status !== 'declined' || pre.carts[k].status === 'declined'
      || (action === 'DELIVER' && data.msg === `Declined:${k}` && pre.carts[k].status === 'paying')),
  },
  {
    name: 'declined-leaves-only-by-retry-or-abandon',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      pre.carts[k].status !== 'declined' || post.carts[k].status === 'declined'
      || (action === 'RETRY' && data.cart === k && post.carts[k].status === 'paying')
      || (action === 'ABANDON' && data.cart === k && post.carts[k].status === 'failed' && inFlight(post, 'Release', k))),
  },
  {
    name: 'returned-only-from-paid-with-refund-and-release',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      post.carts[k].status !== 'returned' || pre.carts[k].status === 'returned'
      || (action === 'RETURN' && data.cart === k && pre.carts[k].status === 'paid'
        && inFlight(post, 'Refund', k) && inFlight(post, 'Release', k))),
  },
  {
    name: 'items-frozen-after-checkout',
    pred: (pre, _a, _d, post) => Object.keys(post.carts).every((k) =>
      ['none', 'open'].includes(pre.carts[k].status) || pre.carts[k].items === post.carts[k].items),
  },
  {
    name: 'terminal-statuses-final',
    pred: (pre, _a, _d, post) => Object.keys(post.carts).every((k) =>
      !TERMINAL.includes(pre.carts[k].status) || pre.carts[k].status === post.carts[k].status),
  },
  {
    name: 'paid-leaves-only-by-return',
    pred: (pre, action, data, post) => Object.keys(post.carts).every((k) =>
      pre.carts[k].status !== 'paid' || post.carts[k].status === 'paid'
      || (action === 'RETURN' && data.cart === k && post.carts[k].status === 'returned')),
  },
  {
    name: 'replies-only-to-pending-requests',
    pred: (pre, action, data, post) => action !== 'DELIVER' || !data.msg.startsWith('Reserve:') || !pre.net.includes(data.msg)
      || post.net.some((m) => (m === `Reserved:${cartOf(data.msg)}` || m === `OutOfStock:${cartOf(data.msg)}`)),
  },
];

