async function toPaying(h: Host, c: string, items: number) {
  await h.open(c);
  for (let i = 0; i < items; i++) await h.add(c);
  await h.checkout(c);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Reserve' && m.from === c)!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Reserved' && m.to === c)!.id);
  assert.equal((await h.cart(c))!.status, 'paying');
}

test('payment timeout releases at once; a late charge is refunded', async () => {
  const h = await createHost();
  assert.equal((await h.paymentTimeout('a')).ok, false);
  await h.open('a');
  assert.equal((await h.paymentTimeout('a')).ok, false);
  await h.add('a'); await h.add('a'); await h.checkout('a');
  assert.equal((await h.paymentTimeout('a')).ok, false); // reserving
  await h.deliver((await h.inFlight())[0].id);
  await h.deliver((await h.inFlight())[0].id);
  assert.deepEqual(await h.paymentTimeout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'abandoning', items: 2 });
  for (const cmd of ['add', 'checkout', 'cancel', 'returnCart', 'retry', 'abandon', 'paymentTimeout'] as const) {
    assert.equal((await h[cmd]('a')).ok, false, cmd);
  }
  const release = (await h.inFlight()).find((m) => m.action === 'Release')!;
  assert.deepEqual({ from: release.from, to: release.to, data: release.data }, { from: 'a', to: 'inventory', data: { qty: 2 } });
  await h.deliver(release.id);
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Charge')!.id);
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
  await h.deliver((await h.inFlight()).find((m) => m.action === 'Charged')!.id);
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 2 });
  const refund = (await h.inFlight()).find((m) => m.action === 'Refund')!;
  assert.deepEqual({ from: refund.from, to: refund.to, data: refund.data }, { from: 'a', to: 'payments', data: { amount: 2 } });
  await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

test('payment timeout then decline fails without refund', async () => {
  const h = await createHost();
  await h.declineCards();
  await toPaying(h, 'a', 1);
  await h.paymentTimeout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 1 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

test('timeout after retry', async () => {
  const h = await createHost();
  await h.declineCards();
  await toPaying(h, 'a', 1);
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'declined');
  await h.acceptCards();
  await h.retry('a');
  await h.paymentTimeout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 1 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

