  assert.deepEqual({ from: refund.from, to: refund.to, data: refund.data }, { from: 'a', to: 'payments', data: { amount: 2 } });
  await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

