// Lockstep conformance: drive src/host.impl.ts and spec/checkout.cjs with the same
// random steps and compare their observable states after every step.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { resolve } from 'node:path';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';
// @ts-ignore: untyped .mjs helper from the polygraph tool
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';

const spec = await loadSpec(resolve('spec/checkout.cjs'));
const CARTS = ['a', 'b', 'c'];

const label = (m: Message) => `${m.action}:${['inventory', 'payments'].includes(m.to) ? m.from : m.to}`;

async function implState(h: Host) {
  const carts: Record<string, { status: string; items: number }> = {};
  for (const c of CARTS) carts[c] = (await h.cart(c)) ?? { status: 'none', items: 0 };
  const s = await h.stock();
  const p = await h.payments();
  const net = (await h.inFlight()).map(label).sort();
  return { carts, available: s.available, reserved: s.reserved, charged: p.charged, declining: p.declining, net };
}

function rng(seed: number) {
  return () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
}

test('implementation and spec agree step by step', async () => {
  for (let seed = 1; seed <= 300; seed++) {
    const r = rng(seed);
    const h = await createHost();
    spec.init();
    for (let i = 0; i < 40; i++) {
      const cart = CARTS[Math.floor(r() * CARTS.length)];
      const k = r();
      if (k < 0.04) { await h.returnCart(cart); spec.actions.RETURN({ cart }); }
      else if (k < 0.07) { await h.retry(cart); spec.actions.RETRY({ cart }); }
      else if (k < 0.09) { await h.abandon(cart); spec.actions.ABANDON({ cart }); }
      else if (k < 0.12) { await h.open(cart); spec.actions.OPEN({ cart }); }
      else if (k < 0.25) { await h.add(cart); spec.actions.ADD({ cart }); }
      else if (k < 0.37) { await h.checkout(cart); spec.actions.CHECKOUT({ cart }); }
      else if (k < 0.45) { await h.cancel(cart); spec.actions.CANCEL({ cart }); }
      else if (k < 0.5) { await h.declineCards(); spec.actions.DECLINE_CARDS({}); }
      else if (k < 0.55) { await h.acceptCards(); spec.actions.ACCEPT_CARDS({}); }
      else {
        const msgs = await h.inFlight();
        if (!msgs.length) continue;
        const m = msgs[Math.floor(r() * msgs.length)];
        await h.deliver(m.id);
        spec.actions.DELIVER({ msg: label(m) });
      }
      assert.deepEqual(JSON.parse(JSON.stringify(spec.getState())), await implState(h), `seed ${seed} step ${i}`);
    }
  }
});
